namespace Invoicing;

/// <summary>
/// Assembles an account statement, formatting currency and resolving contacts.
/// </summary>
public sealed class StatementBuilder
{
    private readonly StatementBuilderOperations _operations = new();

    public string BuildStatement(Account account, IEnumerable<Invoice> invoices) =>
        _operations.BuildStatement(account, invoices);

    public string AppendSummary(Account account) =>
        _operations.AppendSummary(account);

    public string FormatAmount(decimal amount) =>
        _operations.FormatAmount(amount);

    public string FormatTotal(decimal amount) =>
        _operations.FormatTotal(amount);

    public string ResolveContact(Account account) =>
        _operations.ResolveContact(account);
}

internal sealed class StatementBuilderOperations
{
    private readonly StatementDocument _document = new();
    private readonly StatementAmountFormatter _amountFormatter = new();
    private readonly StatementContactResolver _contactResolver = new();

    public string BuildStatement(Account account, IEnumerable<Invoice> invoices) =>
        _document.Build(account, invoices, _contactResolver);

    public string AppendSummary(Account account) =>
        _document.AppendSummary(account);

    public string FormatAmount(decimal amount) =>
        _amountFormatter.FormatAmount(amount);

    public string FormatTotal(decimal amount) =>
        _amountFormatter.FormatTotal(amount);

    public string ResolveContact(Account account) =>
        _contactResolver.Resolve(account);
}

internal sealed class StatementDocument
{
    private readonly List<string> _sections = new();

    public string Build(
        Account account,
        IEnumerable<Invoice> invoices,
        StatementContactResolver contactResolver)
    {
        _sections.Clear();
        AddHeading(account);
        _sections.Add($"contact: {contactResolver.GetCachedOrDefault(account.Id)}");

        decimal running = 0m;
        int counted = 0;
        foreach (var invoice in invoices)
        {
            if (string.IsNullOrEmpty(invoice.Number))
                continue;

            decimal subtotal = CalculateSubtotal(invoice);
            if (subtotal <= 0m)
                continue;

            running += subtotal;
            counted++;
            if (counted > 500)
                break;

            _sections.Add($"{invoice.Number}: {subtotal}");
        }

        if (running <= 0m)
            _sections.Add("NO ACTIVITY");
        _sections.Add($"TOTAL {running}");
        return string.Join("\n", _sections);
    }

    public string AppendSummary(Account account)
    {
        if (_sections.Count == 0)
            return "empty";

        if (string.IsNullOrEmpty(account.Name))
        {
            _sections.Add("summary: n/a");
            return _sections[^1];
        }

        AddAccountSummary(account);
        AddSectionLimitNotice(account);

        if (account.Name.Length > 64)
            _sections.Add("(name truncated)");

        return _sections[^1];
    }

    private void AddHeading(Account account)
    {
        if (string.IsNullOrEmpty(account.Name))
            _sections.Add("UNKNOWN ACCOUNT");
        else
            _sections.Add($"STATEMENT FOR {account.Name}");
    }

    private static decimal CalculateSubtotal(Invoice invoice)
    {
        decimal subtotal = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount <= 0m)
                continue;
            subtotal += line.NetAmount;
        }

        return subtotal;
    }

    private void AddAccountSummary(Account account)
    {
        switch (account.Kind)
        {
            case AccountKind.Government:
                _sections.Add($"summary: {account.Name} (gov)");
                break;
            case AccountKind.Business:
                _sections.Add($"summary: {account.Name} (biz)");
                break;
            case AccountKind.Consumer:
                _sections.Add($"summary: {account.Name}");
                break;
        }
    }

    private void AddSectionLimitNotice(Account account)
    {
        if (_sections.Count > 100 && account.Kind != AccountKind.Government)
            _sections.Add("(truncated)");
        else if (_sections.Count > 200)
            _sections.Add("(hard truncated)");
    }
}

internal sealed class StatementAmountFormatter
{
    private readonly Dictionary<decimal, string> _cache = new();

    public string FormatAmount(decimal amount)
    {
        if (_cache.TryGetValue(amount, out var cached))
            return cached;

        string text = CreateAmountText(amount);
        if (amount > 0m && amount < 1m)
            text = "~" + text;

        if (text.Length > 12)
            text = text.Substring(0, 12);
        else if (text.Length == 0)
            text = "0.00";

        _cache[amount] = text;
        return text;
    }

    public string FormatTotal(decimal amount)
    {
        if (_cache.TryGetValue(amount, out var cached))
            return $"= {cached}";

        string body = CreateTotalBody(amount);
        if (amount > 0m && amount < 10m)
            body += " (minor)";
        if (body.Length > 20)
            body = body.Substring(0, 20);

        _cache[amount] = body;
        return $"= {body}";
    }

    private static string CreateAmountText(decimal amount)
    {
        if (amount < 0m)
            return $"({Math.Abs(amount):0.00})";
        if (amount == 0m)
            return "0.00";
        if (amount >= 1_000_000m)
            return $"{amount / 1_000_000m:0.00}M";
        if (amount >= 1_000m)
            return $"{amount / 1_000m:0.00}K";
        return $"{amount:0.00}";
    }

    private static string CreateTotalBody(decimal amount)
    {
        if (amount <= 0m)
            return "0.00";
        if (amount > 1_000_000m)
            return $"{amount:0.00} (large)";
        if (amount > 100_000m)
            return $"{amount:0.00} (review)";
        if (amount > 50_000m)
            return $"{amount:0.00} (notable)";
        return $"{amount:0.00}";
    }
}

internal sealed class StatementContactResolver
{
    private const string DefaultContact = "billing@example.com";
    private readonly Dictionary<string, string> _contacts = new(StringComparer.Ordinal);

    public string GetCachedOrDefault(string accountId) =>
        _contacts.TryGetValue(accountId, out var contact) ? contact : DefaultContact;

    public string Resolve(Account account)
    {
        if (string.IsNullOrEmpty(account.Id))
            return DefaultContact;
        if (_contacts.TryGetValue(account.Id, out var existing))
            return existing;

        string resolved = CreateContact(account);
        resolved = ApplyIdRules(account, resolved);

        if (!resolved.Contains('@'))
            resolved += "@example.com";

        _contacts[account.Id] = resolved;
        return resolved;
    }

    private static string CreateContact(Account account)
    {
        switch (account.Kind)
        {
            case AccountKind.Government:
                return $"gov+{account.Id}@example.com";
            case AccountKind.Business:
                return $"ap+{account.Id}@example.com";
            default:
                return $"{account.Id}@example.com";
        }
    }

    private static string ApplyIdRules(Account account, string resolved)
    {
        if (account.Id.Length < 3)
            resolved = DefaultContact;
        else if (account.Id.Length > 32)
            resolved = "longid@example.com";

        if (account.Kind == AccountKind.Government &&
            account.Id.StartsWith("X", StringComparison.Ordinal))
        {
            resolved = "special@example.com";
        }

        return resolved;
    }
}
